const RESEND_COOLDOWN_SECONDS = 50;
let resendCooldown = 0;
let resendTimer = null;

function updateResendButton() {
    const btn = document.getElementById('resendEmailBtn');
    if (!btn) return;
    const label = btn.dataset.resendLabel || 'RESEND EMAIL';
    const cooldownPrefix = btn.dataset.resendCooldownPrefix || 'RESEND IN';
    if (resendCooldown > 0) {
        btn.disabled = true;
        btn.textContent = `${cooldownPrefix} ${resendCooldown}s`;
        return;
    }
    btn.disabled = false;
    btn.textContent = label;
}

function startResendCooldown() {
    resendCooldown = RESEND_COOLDOWN_SECONDS;
    updateResendButton();
    if (resendTimer) clearInterval(resendTimer);
    resendTimer = setInterval(() => {
        resendCooldown -= 1;
        updateResendButton();
        if (resendCooldown <= 0) {
            clearInterval(resendTimer);
            resendTimer = null;
        }
    }, 1000);
}

document.addEventListener('DOMContentLoaded', function () {
    // Profile picture upload
    const profilePicture = document.getElementById('profilePicture');
    const profilePreview = document.getElementById('profilePreview');

    if (profilePicture && profilePreview) {
        profilePicture.addEventListener('change', function (e) {
            const file = e.target.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = function (event) {
                    profilePreview.src = event.target.result;
                };
                reader.readAsDataURL(file);
            }
        });
    }

    // Password visibility toggle
    const togglePassword = document.getElementById('togglePassword');
    const password = document.getElementById('password');

    if (togglePassword && password) {
        togglePassword.addEventListener('click', function () {
            const type = password.getAttribute('type') === 'password' ? 'text' : 'password';
            password.setAttribute('type', type);
            togglePassword.innerHTML = type === 'password' ?
                '<i class="fa-regular fa-eye"></i>' :
                '<i class="fa-regular fa-eye-slash"></i>';
        });
    }

    // Confirm password visibility toggle
    const toggleConfirmPassword = document.getElementById('toggleConfirmPassword');
    const confirmPassword = document.getElementById('confirmPassword');

    if (toggleConfirmPassword && confirmPassword) {
        toggleConfirmPassword.addEventListener('click', function () {
            const type = confirmPassword.getAttribute('type') === 'password' ? 'text' : 'password';
            confirmPassword.setAttribute('type', type);
            toggleConfirmPassword.innerHTML = type === 'password' ?
                '<i class="fa-regular fa-eye"></i>' :
                '<i class="fa-regular fa-eye-slash"></i>';
        });
    }

    // Password rules check
    const ruleLength = document.getElementById('ruleLength');
    const ruleUpper = document.getElementById('ruleUpper');
    const ruleLower = document.getElementById('ruleLower');
    const ruleNumber = document.getElementById('ruleNumber');
    const ruleSpecial = document.getElementById('ruleSpecial');
    const submitBtn = document.querySelector('#signupForm button[type="submit"]');

    if (password && submitBtn) {
        password.addEventListener('input', function () {
            const value = password.value;

            const isLong = value.length >= 8;
            const hasUpper = /[A-Z]/.test(value);
            const hasLower = /[a-z]/.test(value);
            const hasNumber = /[0-9]/.test(value);
            const hasSpecial = /[^A-Za-z0-9]/.test(value);

            updateRule(ruleLength, isLong);
            updateRule(ruleUpper, hasUpper);
            updateRule(ruleLower, hasLower);
            updateRule(ruleNumber, hasNumber);
            updateRule(ruleSpecial, hasSpecial);

            const allValid = isLong && hasUpper && hasLower && hasNumber && hasSpecial;
            submitBtn.disabled = !allValid;
        });
    }

    function updateRule(element, condition) {
        if (condition) {
            element.classList.add('valid');
        } else {
            element.classList.remove('valid');
        }
    }

    function safeParseJson(text) {
        if (!text) return null;
        const trimmed = text.trim();
        try {
            return JSON.parse(trimmed);
        } catch (_) {}
        const match = trimmed.match(/\{[\s\S]*\}/);
        if (match) {
            try {
                return JSON.parse(match[0]);
            } catch (_) {}
        }
        return null;
    }

    // Form validation and submission
    const signupForm = document.getElementById('signupForm');
    const loadingOverlay = document.getElementById('loadingOverlay');

    if (signupForm) {
        signupForm.addEventListener('submit', function (e) {
            e.preventDefault();

            const phone = document.getElementById('phone');
            const phoneRegex = /^\+?[0-9]{10,15}$/;

            const value = password.value;
            const isLong = value.length >= 8;
            const hasUpper = /[A-Z]/.test(value);
            const hasLower = /[a-z]/.test(value);
            const hasNumber = /[0-9]/.test(value);
            const hasSpecial = /[^A-Za-z0-9]/.test(value);
            const allValid = isLong && hasUpper && hasLower && hasNumber && hasSpecial;

            if (!phoneRegex.test(phone.value.replace(/\s/g, ''))) {
                new Dialog('Error', 'Please enter a valid phone number (10-15 digits)', {
                    text: 'Okay', action: () => { }, color: '#ff3333'
                });
                return;
            }

            if (!allValid) {
                new Dialog('Error', 'Password does not meet all requirements.', {
                    text: 'Okay', action: () => { }, color: '#ff3333'
                });
                return;
            }

            if (confirmPassword.value !== password.value) {
                new Dialog('Error', 'Passwords do not match', {
                    text: 'Okay', action: () => { }, color: '#ff3333'
                });
                return;
            }

            const recaptchaToken = window.grecaptcha ? grecaptcha.getResponse() : '';
            if (!recaptchaToken) {
                new Dialog('Error', 'Please complete the captcha.', {
                    text: 'Okay', action: () => { }, color: '#ff3333'
                });
                return;
            }

            loadingOverlay.style.display = 'block';

            const data = new FormData(signupForm);
            data.append('g-recaptcha-response', recaptchaToken);

            fetch('https://apilageai.lk/api/auth.php?act=register', {
                method: 'POST',
                body: data
            })
                .then(response => response.text())
                .then(text => {
                    loadingOverlay.style.display = 'none';
                    const result = safeParseJson(text);
                    if (!result) {
                        if (window.grecaptcha) grecaptcha.reset();
                        new Dialog('Error', 'Registration failed. Please try again.', {
                            text: 'Retry', action: () => { }, color: '#ff3333'
                        });
                        return;
                    }

                    if (result.e) {
                        if (window.grecaptcha) grecaptcha.reset();
                        new Dialog('Error', result.m, {
                            text: 'Okay', action: () => { }, color: '#ff3333'
                        });
                        return;
                    }

                    if (window.grecaptcha) grecaptcha.reset();
                    if (result.verify_required) {
                        const fallbackEmail = document.getElementById('email')?.value || '';
                        showRegistrationSuccessModal(result.email || fallbackEmail);
                        return;
                    }

                    new Dialog('Success', result.m, {
                        text: 'Continue', action: () => {
                            window.location.href = 'https://apilageai.lk/auth/login';
                        }, color: '#28a745'
                    });
                })
                .catch(error => {
                    loadingOverlay.style.display = 'none';
                    if (window.grecaptcha) grecaptcha.reset();
                    console.error('Registration error:', error);
                    new Dialog('Error', 'Registration failed. Please try again.', {
                        text: 'Retry', action: () => { }, color: '#ff3333'
                    });
                });
        });
    }
});

// Show registration success modal
function showRegistrationSuccessModal(email) {
    const modal = document.getElementById('registrationSuccessModal');
    const emailDisplay = document.getElementById('registeredEmail');
    
    startResendCooldown();
    if (modal) {
        if (emailDisplay) {
            if (email) {
                emailDisplay.textContent = email;
                emailDisplay.style.display = 'block';
            } else {
                emailDisplay.textContent = '';
                emailDisplay.style.display = 'none';
            }
        }
        modal.style.display = 'flex';
        document.body.style.overflow = 'hidden'; // Prevent scrolling
    } else {
        // Fallback
        alert('Registration successful! Please check ' + email + ' to verify your account.');
        setTimeout(() => {
            window.location.href = 'https://apilageai.lk/auth/login';
        }, 2000);
    }
}

// Close success modal
function closeSuccessModal() {
    const modal = document.getElementById('registrationSuccessModal');
    if (modal) {
        modal.style.display = 'none';
        document.body.style.overflow = ''; // Restore scrolling
    }
    window.location.href = 'https://apilageai.lk/auth/login';
}

// Resend verification email from modal
function resendFromSuccessModal() {
    const emailDisplay = document.getElementById('registeredEmail');
    const email = emailDisplay?.textContent?.trim() || document.getElementById('email')?.value || '';
    const btn = document.getElementById('resendEmailBtn');
    const originalText = btn.innerHTML;

    if (!email) {
        new Dialog('Error', 'Please enter your email first.', {
            text: 'Okay', action: () => { }, color: '#ff3333'
        });
        updateResendButton();
        return;
    }

    if (resendCooldown > 0) {
        return;
    }
    
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Sending...';

    fetch('https://apilageai.lk/auth/resend-verification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: 'email=' + encodeURIComponent(email)
    })
    .then(res => res.json())
    .then(data => {
        btn.disabled = false;
        btn.innerHTML = originalText;
        
        if (data.e) {
            new Dialog('Error', data.m, {
                text: 'Okay', action: () => { }, color: '#ff3333'
            });
        } else {
            new Dialog('Success', 'Verification email sent successfully! Please check your inbox.', {
                text: 'Okay', action: () => { }, color: '#28a745'
            });
            startResendCooldown();
        }
    })
    .catch(err => {
        btn.disabled = false;
        btn.innerHTML = originalText;
        console.error('Resend error:', err);
        new Dialog('Error', 'Failed to resend email. Please try again.', {
            text: 'Okay', action: () => { }, color: '#ff3333'
        });
    });
}
